CREATE OR REPLACE FUNCTION public.account_erasure_executor_recover(p_profile_id uuid, p_request_id uuid, p_token uuid, p_evidence jsonb, p_auth_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
